async function load(){setLoading(true);setError('');const reportPeriod=main==='reports'||main==='expenses'?'month':period;try{if(localMode){setData(localSnapshot(reportPeriod,month,demo));return;}const r=await fetch(`/api/ledger?period=${reportPeriod}&month=${month}&demo=${demo?'1':'0'}`);if(r.status===401){setLocalMode(true);setData(localSnapshot(reportPeriod,month,demo));return;}const j=await r.json() as Data & {error?:string};if(!r.ok)throw Error(j.error);setData(j);}catch(e){setError(e instanceof Error?e.message:'Ошибка загрузки');}finally{setLoading(false);}}
