async function send(body:Record<string,unknown>){if(localMode){const source=localSource();if(data?.revision!==source.revision)throw Error('Данные изменились в другой вкладке. Обновите страницу и повторите операцию.');const ledger=mutate(source.ledger,body),calculated=calculate(ledger);ledger.allocations=calculated.allocations;localStorage.setItem(LOCAL_LEDGER,JSON.stringify({ledger,revision:source.revision+1}));return;}const r=await fetch('/api/ledger',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,revision:data?.revision})});const j=await r.json() as {error?:string};if(!r.ok)throw Error(j.error);}
